const wrongCursorByBlock = new Map();
const globalWrongTexts = new Set();
const globalWrongTuples = new Set();
const F = (blockKey, source, prompt, correct, reason) => {
  const index = wrongCursorByBlock.get(blockKey) ?? 0;
  const wrongs = wrongSets[blockKey]?.[index];
  if (!wrongs || wrongs.length !== 3) throw new Error(`${blockKey}-${index + 1}: explicit card-specific distractors are missing.`);
  const tuple = wrongs.map((wrong) => wrong.text).sort().join("\u001f");
  if (globalWrongTuples.has(tuple)) throw new Error(`${blockKey}-${index + 1}: repeated distractor tuple.`);
  globalWrongTuples.add(tuple);
  for (const wrong of wrongs) {
    if (!wrong.text || !wrong.why) throw new Error(`${blockKey}-${index + 1}: incomplete distractor.`);
    if (globalWrongTexts.has(wrong.text)) throw new Error(`${blockKey}-${index + 1}: repeated distractor text: ${wrong.text}`);
    globalWrongTexts.add(wrong.text);
  }
  wrongCursorByBlock.set(blockKey, index + 1);
  return { source, prompt, correct, reason, wrongs };
};

